"""Pins on the self-healing launcher wrapper generated by
``write_launcher_script`` in ``deploy/install.sh``.

The wrapper is the supervisor entry point on both macOS (launchd
ProgramArguments) and Linux (systemd ExecStart). Its job beyond the bare
``exec``: when the current release's venv interpreter is missing/corrupt (a
half-staged release), roll forward to the newest sibling release that still
has a runnable venv and rewrite ``current_version`` BEFORE exec — the in-venv
``mobaide.launcher`` (which owns crash-loop rollback) cannot run without its
own interpreter, so this recovery must happen one level up.

Mixes pure-text/AST pins (the convention in ``test_install_sh*.py``) with a
few executable tests that generate the wrapper and run it against a fake
prefix — the recovery logic is the load-bearing new behaviour, worth
exercising end to end.
"""
from __future__ import annotations

import shlex
import subprocess
from pathlib import Path

import pytest

from test_install_script_trap import _BASH, _sh_function_body


_REQUIRES_BASH = pytest.mark.skipif(_BASH is None, reason="bash not available")


def test_wrapper_recovers_on_missing_interpreter() -> None:
    body = _sh_function_body("write_launcher_script")
    assert '[ ! -x "$py" ]' in body, (
        "wrapper must detect a missing/non-executable current interpreter "
        "before exec so it can self-heal. Body:\n" + repr(body)
    )


def test_wrapper_uses_portable_numeric_version_sort_not_sort_v() -> None:
    """``sort -V`` is GNU-only and breaks on BSD/macOS ``sort``; the wrapper
    must use the portable numeric multi-key form."""
    body = _sh_function_body("write_launcher_script")
    assert "sort -t. -k1,1n -k2,2n -k3,3n" in body, (
        "wrapper must pick the newest sibling with a portable numeric "
        "`sort -t. -k1,1n ...`. Body:\n" + repr(body)
    )
    # Only check non-comment lines for `sort -V` — the production code's
    # explanatory comment legitimately says "NOT `sort -V`" to document why
    # the portable form is used; we must not flag that prose as a violation.
    non_comment_lines = [
        ln for ln in body.splitlines() if not ln.lstrip().startswith("#")
    ]
    non_comment_body = "\n".join(non_comment_lines)
    assert "sort -V" not in non_comment_body, (
        "wrapper must NOT use `sort -V` as a command — it is GNU-only and the "
        "macOS BSD sort would error / mis-sort. Non-comment body:\n"
        + repr(non_comment_body)
    )


def test_wrapper_rewrites_current_version_atomically() -> None:
    body = _sh_function_body("write_launcher_script")
    assert "current_version.tmp" in body and "mv " in body, (
        "wrapper must rewrite current_version via tmp + mv (atomic rename). "
        "Body:\n" + repr(body)
    )


def test_wrapper_exits_70_when_no_runnable_release() -> None:
    body = _sh_function_body("write_launcher_script")
    assert "exit 70" in body, (
        "wrapper must exit 70 (not crash-loop silently) when no release has a "
        "runnable venv. Body:\n" + repr(body)
    )


def test_wrapper_certifi_block_is_darwin_only() -> None:
    """Forcing ``SSL_CERT_FILE=certifi`` on Linux could exclude a corporate
    ``/etc/ssl`` root CA and break relay TLS — the certifi export must be
    gated to macOS."""
    body = _sh_function_body("write_launcher_script")
    assert 'PLATFORM" = "darwin"' in body, (
        "the SSL_CERT_FILE/certifi block must be emitted only when "
        'PLATFORM is darwin. Body:\n' + repr(body)
    )
    # The certifi export must sit inside the darwin guard, after recovery.
    # Use "export SSL_CERT_FILE" (the actual export statement) rather than the
    # bare token "SSL_CERT_FILE" — the latter also appears in a prose comment
    # ("respects an operator-set SSL_CERT_FILE") that precedes the guard and
    # would give a false-positive position before the darwin check.
    darwin_pos = body.find('PLATFORM" = "darwin"')
    certifi_pos = body.find("export SSL_CERT_FILE")
    assert darwin_pos >= 0 and certifi_pos > darwin_pos, (
        "SSL_CERT_FILE export must be inside the darwin guard. Body:\n"
        + repr(body)
    )


def test_systemd_execstart_points_at_wrapper() -> None:
    body = _sh_function_body("install_systemd_unit")
    assert "write_launcher_script" in body, (
        "install_systemd_unit must generate the wrapper. Body:\n" + repr(body)
    )
    assert "bin/mobaide-agent-launcher.sh" in body, (
        "install_systemd_unit ExecStart must point at the launcher wrapper. "
        "Body:\n" + repr(body)
    )
    assert "env bash -c" not in body, (
        "install_systemd_unit must no longer use the inline `env bash -c` "
        "ExecStart (it bypassed self-heal). Body:\n" + repr(body)
    )


def test_launchd_plist_generates_wrapper() -> None:
    body = _sh_function_body("install_launchd_plist")
    assert "write_launcher_script" in body, (
        "install_launchd_plist must generate the launcher via the shared "
        "write_launcher_script. Body:\n" + repr(body)
    )


def test_stage_release_rejects_unsafe_version() -> None:
    """install.sh stage_release must reject a manifest version with path-unsafe
    characters before it becomes a releases/<v> path component (SEC-02)."""
    body = _sh_function_body("stage_release")
    assert 'case "$target_version" in' in body, (
        "stage_release must guard target_version with a case charset check "
        "before building release_dir. Body:\n" + repr(body)
    )
    assert "[!0-9A-Za-z.+_-]" in body, (
        "stage_release must reject version chars outside the safe set "
        "(blocks / \\ and traversal). Body:\n" + repr(body)
    )


def _generate_wrapper(prefix: Path) -> Path:
    """Run ``write_launcher_script`` (PLATFORM=linux) to emit the wrapper."""
    assert _BASH is not None
    body = _sh_function_body("write_launcher_script")
    harness = (
        "set -u\n"
        "PLATFORM=linux\n"
        f"MOBAIDE_AGENT_PREFIX={shlex.quote(str(prefix))}\n"
        f"write_launcher_script() {{\n{body}\n}}\n"
        "write_launcher_script\n"
    )
    proc = subprocess.run(
        [_BASH, "-c", harness], capture_output=True, text=True
    )
    assert proc.returncode == 0, f"wrapper generation failed: {proc.stderr}"
    wrapper = prefix / "bin" / "mobaide-agent-launcher.sh"
    assert wrapper.is_file()
    return wrapper


def _make_release(prefix: Path, version: str) -> None:
    """Create ``releases/<version>/venv/bin/python`` as an executable stub that
    echoes its version, so ``exec "$py" -m mobaide.launcher`` is observable."""
    bindir = prefix / "releases" / version / "venv" / "bin"
    bindir.mkdir(parents=True, exist_ok=True)
    py = bindir / "python"
    py.write_text(f'#!/bin/sh\necho "RAN {version}"\n', encoding="utf-8")
    py.chmod(0o755)


def _run_wrapper(wrapper: Path, prefix: Path) -> subprocess.CompletedProcess[str]:
    assert _BASH is not None
    return subprocess.run(
        [_BASH, str(wrapper)],
        capture_output=True,
        text=True,
        env={"MOBAIDE_AGENT_PREFIX": str(prefix), "PATH": "/usr/bin:/bin"},
    )


@_REQUIRES_BASH
def test_recovers_to_newest_sibling_when_current_venv_missing(tmp_path) -> None:
    prefix = tmp_path / "mobaide"
    (prefix).mkdir()
    _make_release(prefix, "0.2.0")
    _make_release(prefix, "0.2.13")
    # current_version points at a release with NO venv → must recover.
    (prefix / "current_version").write_text("0.2.99\n", encoding="utf-8")

    wrapper = _generate_wrapper(prefix)
    result = _run_wrapper(wrapper, prefix)

    assert result.returncode == 0, result.stderr
    assert "RAN 0.2.13" in result.stdout, (
        f"expected exec into the newest sibling 0.2.13; stdout={result.stdout!r} "
        f"stderr={result.stderr!r}"
    )
    assert (prefix / "current_version").read_text().strip() == "0.2.13"
    assert "recovered to '0.2.13'" in result.stderr


@_REQUIRES_BASH
def test_version_sort_prefers_higher_numeric_not_lexical(tmp_path) -> None:
    """0.10.0 must outrank 0.9.0 (numeric, not lexical) — the BSD-portable
    sort guard."""
    prefix = tmp_path / "mobaide"
    prefix.mkdir()
    _make_release(prefix, "0.9.0")
    _make_release(prefix, "0.10.0")
    (prefix / "current_version").write_text("9.9.9\n", encoding="utf-8")

    wrapper = _generate_wrapper(prefix)
    result = _run_wrapper(wrapper, prefix)

    assert result.returncode == 0, result.stderr
    assert "RAN 0.10.0" in result.stdout, (
        f"expected 0.10.0 to outrank 0.9.0 numerically; stdout={result.stdout!r}"
    )


@_REQUIRES_BASH
def test_exits_70_when_no_runnable_release(tmp_path) -> None:
    prefix = tmp_path / "mobaide"
    (prefix / "releases").mkdir(parents=True)
    (prefix / "current_version").write_text("0.2.0\n", encoding="utf-8")

    wrapper = _generate_wrapper(prefix)
    result = _run_wrapper(wrapper, prefix)

    assert result.returncode == 70, (
        f"expected exit 70 with no runnable release; rc={result.returncode} "
        f"stderr={result.stderr!r}"
    )


@_REQUIRES_BASH
def test_no_recovery_when_current_venv_is_runnable(tmp_path) -> None:
    """Healthy boot: an intact current release execs directly, current_version
    untouched."""
    prefix = tmp_path / "mobaide"
    prefix.mkdir()
    _make_release(prefix, "0.2.13")
    (prefix / "current_version").write_text("0.2.13\n", encoding="utf-8")

    wrapper = _generate_wrapper(prefix)
    result = _run_wrapper(wrapper, prefix)

    assert result.returncode == 0, result.stderr
    assert "RAN 0.2.13" in result.stdout
    assert "recovered" not in result.stderr
    assert (prefix / "current_version").read_text().strip() == "0.2.13"


@_REQUIRES_BASH
def test_ignores_staging_and_old_scratch_dirs(tmp_path) -> None:
    """Recovery must skip ``.staging-*`` / ``.old-*`` scratch dirs even if they
    contain a venv python."""
    prefix = tmp_path / "mobaide"
    prefix.mkdir()
    _make_release(prefix, "0.2.0")
    # A scratch dir that happens to have a runnable venv must NOT be chosen.
    _make_release(prefix, ".staging-9.9.9-123")
    (prefix / "current_version").write_text("0.2.99\n", encoding="utf-8")

    wrapper = _generate_wrapper(prefix)
    result = _run_wrapper(wrapper, prefix)

    assert result.returncode == 0, result.stderr
    assert "RAN 0.2.0" in result.stdout, (
        f"recovery must ignore scratch dirs; stdout={result.stdout!r}"
    )
    assert (prefix / "current_version").read_text().strip() == "0.2.0"


@_REQUIRES_BASH
def test_ignores_non_numeric_foreign_release_dir(tmp_path) -> None:
    """Recovery must pick only numeric-dotted releases — an operator-introduced
    foreign dir with a venv (e.g. a manual backup) is NOT a candidate, matching
    the strict filter the in-venv launcher applies (CORR-02)."""
    prefix = tmp_path / "mobaide"
    prefix.mkdir()
    _make_release(prefix, "0.2.0")
    _make_release(prefix, "backup")        # foreign non-numeric name + venv
    _make_release(prefix, "0.2.0-custom")  # has letters/hyphen → not numeric
    (prefix / "current_version").write_text("0.2.99\n", encoding="utf-8")

    wrapper = _generate_wrapper(prefix)
    result = _run_wrapper(wrapper, prefix)

    assert result.returncode == 0, result.stderr
    assert "RAN 0.2.0" in result.stdout, (
        f"recovery must pick only numeric-dotted releases; stdout={result.stdout!r}"
    )
    assert (prefix / "current_version").read_text().strip() == "0.2.0"
